comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]

def orfs(s, min_aa=50):
    res=[]
    for strand,s2 in [(1,s),( -1,rc(s))]:
        for frame in range(3):
            i=frame
            while i < len(s2)-2:
                if s2[i:i+3]=="ATG":
                    j=i
                    while j < len(s2)-2:
                        cod=s2[j:j+3]
                        if cod in ("TAA","TAG","TGA"):
                            break
                        j+=3
                    aa=(j-i)//3
                    if aa>=min_aa:
                        if strand==1:
                            start=i+1; end=j+3
                        else:
                            start=len(s)-j-3+1; end=len(s)-i
                        res.append((strand,start,end,aa,aa*3+3))
                    i=j
                else:
                    i+=3
    return res

for o in sorted(orfs(seq), key=lambda x:-x[3]):
    print(o)

seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip()

# find duplicated k-mers (exact repeats)
from collections import defaultdict
for k in (10,12,15,20):
    d=defaultdict(list)
    for i in range(len(seq)-k+1):
        d[seq[i:i+k]].append(i)
    reps={s:p for s,p in d.items() if len(p)>1}
    print(f"k={k}: {len(reps)} repeated k-mers")
    for s,p in list(reps.items())[:10]:
        print("   ", s, [x+1 for x in p])
